"""Render ``include/mylab_mex_api.h`` from the table in :mod:`mylab.mex.spec`.

Run ``python scripts/gen_mex_header.py`` after changing the table.
"""

from __future__ import annotations

from pathlib import Path

from .spec import ABI_VERSION, c_decl, entries

API_HEADER = Path(__file__).resolve().parent / "include" / "mylab_mex_api.h"

_PREAMBLE = """\
/*
 * mylab_mex_api.h - the function table behind mylab's mex.h.
 *
 * GENERATED by scripts/gen_mex_header.py from mylab/mex/spec.py: do not edit by hand.
 * Part of mylab (MIT licence).  Include "mex.h" or "matrix.h", not this file.
 *
 * Every mx and mex function below is a small inline function that calls
 * through the table mylab passes to the MEX file, then checks the table's
 * "pending" flag.  mylab sets that flag when a call raised an error (or when
 * the function was mexErrMsgTxt), and the check then unwinds straight back
 * to the entry point that called mexFunction.
 */
#ifndef MYLAB_MEX_API_H
#define MYLAB_MEX_API_H

#define MYLAB_MEX_ABI {abi}

typedef struct mylab_mex_api {{
    int abi_version;   /* MYLAB_MEX_ABI of the mylab that filled the table */
    int pending;       /* non-zero: an error is waiting, unwind now */
"""


def render() -> str:
    lines = [_PREAMBLE.format(abi=ABI_VERSION)]
    items = entries()
    for e in items:
        params = ", ".join(c_decl(t, "") for t, _ in e.args) or "void"
        lines.append(f"    {c_decl(e.ret, '(*' + e.name + ')')}({params});\n")
    lines.append("} mylab_mex_api;\n\n")
    lines.append("/* Defined in mylab_mex_entry.c, which mylab's mex compiles into every MEX file. */\n")
    lines.append("MYLAB_EXTERN_C mylab_mex_api *mylab_mex_table;\n")
    lines.append("MYLAB_EXTERN_C MYLAB_NORETURN void mylab_mex_unwind(void);\n\n")
    lines.append("#define MYLAB_MEX_CHECK() do { if (mylab_mex_table->pending) mylab_mex_unwind(); } while (0)\n\n")
    for e in items:
        if e.internal:
            continue
        params = ", ".join(c_decl(t, n) for t, n in e.args) or "void"
        call = f"mylab_mex_table->{e.name}({', '.join(n for _, n in e.args)})"
        if e.ret == "void":
            body = f"{call}; MYLAB_MEX_CHECK();"
        else:
            body = f"{c_decl(e.ret, 'r')} = {call}; MYLAB_MEX_CHECK(); return r;"
        lines.append(f"MYLAB_INLINE {c_decl(e.ret, e.name)}({params})\n{{ {body} }}\n")
    lines.append("\n#endif /* MYLAB_MEX_API_H */\n")
    return "".join(lines)
